import{_ as r,C as n,o as s,c as d,a2 as o,j as t,a as e,E as l}from"./chunks/framework.Dx-TCpNt.js";const x=JSON.parse('{"title":"KomaYomi — Manga Learner ドキュメント","titleTemplate":false,"description":"KomaYomi（Manga Learner）ドキュメント — 漫画で言語を学び、ノートを取る。日中英の比較リーディング、コマ検出、位置合わせ、注釈に対応。","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi（Manga Learner）ドキュメント — 漫画で言語を学び、ノートを取る。日中英の比較リーディング、コマ検出、位置合わせ、注釈に対応。","title":"KomaYomi — Manga Learner ドキュメント","hero":{"name":"KomaYomi","text":"Manga Learner","tagline":"漫画で言語を学び、ノートを取る。コマ、比較、ノートはすべて手元のマシンに。","image":{"src":"/assets/screenshots/compare-reading.png","alt":"3言語の比較リーダー"},"actions":[{"theme":"brand","text":"はじめる","link":"/ja/guide/introduction"},{"theme":"alt","text":"データ形式","link":"/ja/data-format"}]},"features":[{"title":"まずコマから","details":"XYカットによる自動検出に加え、手描き、結合、番号付け、再利用できるレイアウトテンプレート。コマ数が一致する場合、以前の注釈は再マッピングされます。"},{"title":"最大3言語を比較","details":"並べて表示または重ね表示、言語ごとのマスク、ホイールズームとパン、さらにページ／コマ／アンカー／グリッドの位置合わせと再利用できるプリセット。"},{"title":"持ち運べるノート","details":"ページ単位またはコマ単位の Markdown ノート、タグ、出典、スクラッチパッド、全文検索、そして LLM に貼り付けるためのワンクリック「コンテキストをコピー」。"},{"title":"持ち出せる出力","details":"画像フォルダ付きの HTML または単一の埋め込みファイルとしてエクスポートし、ページ／コマ／コラージュの PNG を書き出し、すべてを `.mnproj` プロジェクトとして移せます。"}]},"headers":[],"relativePath":"ja/index.md","filePath":"ja/index.md","lastUpdated":1794727111000}'),m={name:"ja/index.md"};function c(p,a,g,u,_,f){const i=n("Badge");return s(),d("div",null,[a[4]||(a[4]=o('<h2 id="komayomi-とは" tabindex="-1">KomaYomi とは？ <a class="header-anchor" href="#komayomi-とは" aria-label="Permalink to &quot;KomaYomi とは？&quot;">​</a></h2><p>KomaYomi（<strong>Manga Learner</strong>）は、漫画で言語を学び、ノートを取るための<strong>ローカル Web アプリケーション</strong>です。同じ漫画の日本語・中国語・英語版を並べて読み比べ、その場でノートを取れます。ページ画像は <code>raw/</code> フォルダに置いたままで、コマ、ノート、タグ、位置合わせのオフセット、注釈はすべて <code>data/</code> 以下のプレーンな JSON に保存されます。エクスポートしない限り、データがマシンの外に出ることはありません。</p><p>著作権のある素材を配布するためではなく、学習や翻訳レビューのために設計されています。自分のスキャンを用意し、アプリにフォルダを指定して、1ページずつ作業してください。</p><h2 id="現状の概要" tabindex="-1">現状の概要 <a class="header-anchor" href="#現状の概要" aria-label="Permalink to &quot;現状の概要&quot;">​</a></h2><p>KomaYomi は <strong>0.1.0 で、活発に開発中</strong>です。このドキュメントでは、現在存在する機能と計画中の機能を区別して説明します。</p><div class="status-list"><div><strong>現在動作するもの</strong> — ライブラリのスキャン、XYカットによるコマ検出、手動でのコマ編集、コマ／レイアウトテンプレート、ベクター注釈（矩形、楕円、矢印、テキスト）、マスクと4種類の位置合わせモードを備えた比較リーダー、検索付き Markdown ノート、HTML と PNG のエクスポート、バックアップ ZIP と WebDAV／ネットワークターゲットへのアップロード、オンデマンド LRU キャッシュを備えた WebDAV／ネットワーク画像ソース、`.mnproj` プロジェクトのエクスポート／インポート、CLI バッチツール。</div><div><strong>計画中</strong> — アプリ内でのコマグループ編集。PDF、Word（docx）、語彙リストのエクスポート。オフライン書き込みキュー。スケジュールバックアップ。ネイティブのモバイルアプリ。より広範な統合テスト。</div></div>',6)),t("p",null,[a[0]||(a[0]=e("このサイトで ",-1)),l(i,{type:"warning",text:"予定"}),a[1]||(a[1]=e(" と表示されているものは",-1)),a[2]||(a[2]=t("strong",null,"まだ実装されていません",-1)),a[3]||(a[3]=e("。コードにない挙動をページが説明している場合は、この注記を優先し、その機能は利用できないものと考えてください。",-1))]),a[5]||(a[5]=o('<h2 id="次に読む" tabindex="-1">次に読む <a class="header-anchor" href="#次に読む" aria-label="Permalink to &quot;次に読む&quot;">​</a></h2><ul><li>はじめてですか？ <a href="/KomaYomi-docs/ja/guide/introduction">はじめに</a> を読んでから <a href="/KomaYomi-docs/ja/guide/installation">インストールと起動</a> へ。</li><li>全体像を知りたい？ <a href="/KomaYomi-docs/ja/concepts">基本概念</a> から始めてください。</li><li>JSON を扱う、プラグインを書く？ <a href="/KomaYomi-docs/ja/data-format">データ形式</a> と <a href="/KomaYomi-docs/ja/extending">レイアウトテンプレートとプラグイン</a> へ。</li><li>ページが見つからない、エクスポートが壊れた？ <a href="/KomaYomi-docs/ja/faq">FAQ とトラブルシューティング</a> を見てください。</li></ul><div class="tip custom-block"><p class="custom-block-title">ドキュメントの言語</p><p>英語が主要な言語です。中国語訳は <code>/zh/</code>、日本語訳は <code>/ja/</code> にあります。各ページはそれぞれの状態を個別に示します。</p></div>',3))])}const T=r(m,[["render",c]]);export{x as __pageData,T as default};
